def copy_state(apps, schema_editor):
    Book = apps.get_model("catalog", "Book")
    for book in Book.objects.all():
        if book.archived:
            book.state = "archived"
        elif not book.published:
            book.state = "draft"
        else:
            book.state = "published"
        book.save(update_fields=["state"])
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


def clear_blank_isbns(apps, schema_editor):
    Book = apps.get_model("catalog", "Book")
    Book.objects.filter(isbn="").update(isbn=None)
    for book in Book.objects.exclude(isbn__isnull=True):
        cleaned = re.sub(r"[^0-9Xx]", "", book.isbn or "").upper() or None
        if cleaned != book.isbn:
            book.isbn = cleaned
            book.save(update_fields=["isbn"])
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


